package com.itsm.changemanagement.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="configuration_records", uniqueConstraints=@UniqueConstraint(columnNames={"config_type","config_key"})) public class ConfigRecord {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="config_type",nullable=false)private String configType;@Column(name="config_key",nullable=false)private String configKey;@Column(nullable=false,columnDefinition="longtext")private String payload;private boolean active=true;private LocalDateTime createdAt=LocalDateTime.now();private LocalDateTime updatedAt=LocalDateTime.now();public ConfigRecord(){}public ConfigRecord(String t,String k,String p){configType=t;configKey=k;payload=p;}public Long getId(){return id;}public String getConfigType(){return configType;}public String getConfigKey(){return configKey;}public String getPayload(){return payload;}public void setPayload(String p){payload=p;updatedAt=LocalDateTime.now();}public boolean isActive(){return active;}public void setActive(boolean a){active=a;}public LocalDateTime getCreatedAt(){return createdAt;}public LocalDateTime getUpdatedAt(){return updatedAt;}}
